with filtered as (select *, round(discount * 0.9, 2) as discount_adjusted, coalesce(channel, 'NONE') as resolved_channel from orders where status = 'PENDING'), eligible as (select s.* from filtered s where exists (select 1 from shipments ch where ch.order_id = s.id and ch.shipped_date <= s.order_date)), attributed as (select e.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from eligible e inner join promotions pr on e.channel = pr.channel and e.order_date >= pr.starts_on and e.order_date < pr.ends_on + interval '7' day), cleaned as (select id, customer_id, store_id, order_date, amount, discount_adjusted, resolved_channel, promo_id, promo_code, discount_pct, amount * promo_id as amount_times_promo_id from attributed where channel is not null and shipping_fee <= 32), with_window as (select src.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from cleaned src left join subscriptions sub on src.customer_id = sub.customer_id and src.order_date >= sub.start_date and src.order_date < sub.end_date + interval 7 days) select s.id, s.customer_id, s.store_id, s.amount, s.resolved_channel, s.promo_id, s.discount_pct, s.amount_times_promo_id, s.subscription_id, (select max(t2.balance) from accounts t2 where t2.customer_id = s.customer_id) as max_account_balance from with_window s order by store_id nulls last, amount
